def stop(self) -> bool:
    """
    Stop Atlas safely.
    """

    if self.application is None:
        return True

    logger.info(
        "Stopping AtlasApplication"
    )

    stopped = self.application.stop()

    if not stopped:
        self.exit_code = max(
            self.exit_code,
            1,
        )

        logger.warning(
            "Atlas stopped with one or more shutdown errors"
        )

    return stopped

def execute(self) -> int:
    """
    Run the full Atlas process lifecycle.
    """

    self.install_signal_handlers()

    try:
        if not self.start():
            return self.exit_code

        self.run_forever()

    except KeyboardInterrupt:
        self.shutdown_reason = (
            "Keyboard interrupt"
        )

        logger.warning(
            "Keyboard interrupt received"
        )

    except Exception as exc:
        self.exit_code = 1

        self.shutdown_reason = (
            f"Fatal error: {exc}"
        )

        logger.critical(
            "Fatal Atlas error: %s",
            exc,
        )

        logger.debug(
            "Fatal traceback:\n%s",
            traceback.format_exc(),
        )

    finally:
        try:
            self.stop()
        except Exception:
            self.exit_code = 1

            logger.exception(
                "Fatal error during Atlas shutdown"
            )

        logger.info(
            "Atlas process finished | "
            "exit_code=%s | reason=%s",
            self.exit_code,
            (
                self.shutdown_reason
                or "Normal shutdown"
            ),
        )

    return self.exit_code

def stop(self) -> bool:
    """
    Stop Atlas services in reverse dependency order.
    """

    logger.info(
        "=================================================="
    )
    logger.info(
        "ATLAS SHUTDOWN SEQUENCE"
    )
    logger.info(
        "=================================================="
    )

    shutdown_errors = 0

    try:
        self.runtime.stop()
    except Exception as exc:
        shutdown_errors += 1
        self._record_error(
            phase="runtime_stop",
            error=exc,
        )

    shutdown_order = (
        ("controller", self.controller),
        ("market_loop", self.market_loop),
        ("execution", self.execution),
        ("market_feed", self.market_feed),
        ("scheduler", self.scheduler),
    )

    for name, service in shutdown_order:
        try:
            self._stop_service(
                name=name,
                service=service,
            )
        except Exception as exc:
            shutdown_errors += 1
            self._record_error(
                phase=f"shutdown:{name}",
                error=exc,
            )

            logger.exception(
                "Service shutdown failed: %s",
                name,
            )

    try:
        self.lifecycle.stop_all()
    except Exception as exc:
        shutdown_errors += 1
        self._record_error(
            phase="lifecycle_stop_all",
            error=exc,
        )

        logger.exception(
            "Lifecycle shutdown failed"
        )

    self.running = False
    self.stopped_at = datetime.now(UTC).isoformat()
    self.started_services.clear()

    try:
        self.runtime.shutdown()
    except Exception as exc:
        shutdown_errors += 1
        self._record_error(
            phase="runtime_shutdown",
            error=exc,
        )

    if shutdown_errors:
        logger.warning(
            "Atlas stopped with %s shutdown error(s)",
            shutdown_errors,
        )
        return False

    logger.info(
        "ATLAS SYSTEM OFFLINE"
    )
    return True

def stop(self) -> bool:
    """
    Stop the worker thread gracefully.
    """

    with self.lock:
        if not self.running:
            logger.info(
                "Market Loop is already stopped"
            )
            return True

        self.running = False
        self.stop_event.set()

        thread = self.thread

    if (
        thread is not None
        and thread.is_alive()
        and thread is not threading.current_thread()
    ):
        thread.join(
            timeout=max(
                5.0,
                self.interval + 1.0,
            )
        )

    with self.lock:
        still_alive = bool(
            self.thread
            and self.thread.is_alive()
        )

        self.stopped_at = datetime.now(
            UTC
        ).isoformat()

        if not still_alive:
            self.thread = None

    if still_alive:
        logger.warning(
            "Market Loop thread did not stop within timeout"
        )
        return False

    logger.info(
        "Market Loop stopped"
    )

    return True

def worker(self) -> None:
    """
    Execute continuous market cycles until shutdown.
    """

    logger.debug(
        "Market Loop worker entered"
    )

    while self.running:
        cycle_started = time.perf_counter()

        try:
            self.run_cycle()

        except Exception as exc:
            self._record_error(
                phase="cycle",
                error=exc,
            )

            logger.exception(
                "Market cycle failed"
            )

        cycle_duration = (
            time.perf_counter()
            - cycle_started
        )

        with self.lock:
            self.metrics["cycles"] += 1
            self.metrics["latency"] = round(
                cycle_duration,
                4,
            )

            self.last_cycle_duration = round(
                cycle_duration,
                4,
            )

            self.last_cycle = datetime.now(
                UTC
            ).isoformat()

        self.stop_event.wait(
            self.interval
        )

    logger.debug(
        "Market Loop worker exited"
    )

def start(
    self,
) -> None:
    """
    Start MarketFeedService and its public-data provider.
    """

    self.service.start()

    logger.info(
        "Market Feed started through MarketFeedService."
    )

def stop(
    self,
) -> None:
    """
    Stop MarketFeedService and disconnect its provider.
    """

    self.service.stop()

    logger.info(
        "Market Feed stopped through MarketFeedService."
    )

def _to_legacy_candle_row(
    candle: MarketCandle,
) -> list[Any]:
    metadata = dict(
        candle.metadata or {}
    )

    return [
        MarketFeed._to_milliseconds(
            candle.open_time
        ),
        str(candle.open),
        str(candle.high),
        str(candle.low),
        str(candle.close),
        str(candle.volume),
        MarketFeed._to_milliseconds(
            candle.close_time
            or candle.open_time
        ),
        str(
            metadata.get(
                "quote_asset_volume",
                0.0,
            )
        ),
        int(
            metadata.get(
                "number_of_trades",
                0,
            )
        ),
        str(
            metadata.get(
                "taker_buy_base_volume",
                0.0,
            )
        ),
        str(
            metadata.get(
                "taker_buy_quote_volume",
                0.0,
            )
        ),
        metadata.get(
            "ignore",
            "0",
        ),
    ]
